// 新source不发ID；原政治/Office两头与真正result各有独立分配序，完整冷验拒缺源或孤缓存。
#include "political_dismissal_receipts.hpp"
#include "hanmo/resident/command_contract.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <set>
#include <map>
namespace hanmo::resident {namespace {
// 此结构门不代替原撤职授权；只固定永久结果、共同头及历史裁剪后的来源对应。
Status bindings(const CommonStore& c,const PoliticalDismissalSourceState& s){auto valid=validate_political_dismissal_state_layout(s);if(!valid.ok)return valid;std::set<Integer> fact_numbers;std::map<StableId,std::size_t> positions;std::size_t pos=0;for(const auto& row:c.state().facts.rows()){positions.emplace(row.first,pos++);const auto colon=row.first.rfind(':');if(colon!=StableId::npos){auto n=organization_instance_sequence(row.first,row.first.substr(0,colon));if(n)fact_numbers.insert(*n);}}
 Integer previous_result=0,previous_revision=0,previous_tick=-1;std::map<StableId,Integer> requests;std::set<StableId> results;std::size_t previous_position=0;bool have=false;
 for(const auto& row:s.dismissals.rows()){const auto& src=row.second.source;if(!row.second.actual_result)return common_failure("PoliticalDismissalPermanentResultRequired",row.first);const auto& b=*row.second.actual_result;const auto n=organization_instance_sequence(src.dismissal_fact_id,"politics"),office=organization_instance_sequence(src.office_change_fact_id,"organization"),result=organization_instance_sequence(b.result_id,"result");const auto* fact=c.state().facts.find(row.first);const auto* changed=c.state().facts.find(src.office_change_fact_id);const auto* request=c.state().request_sequences.find(b.actor_id);
  if(row.first!=src.dismissal_fact_id||!n||!office||!result||*n==std::numeric_limits<Integer>::max()||*office!=*n+1||*n<=previous_result||*result<=*office||*result>=c.state().next_instance_id||fact_numbers.count(*result)||!results.insert(b.result_id).second||!fact||fact->id!=row.first||fact->kind!="political_office_dismissed"||fact->domain!="politics"||!changed||changed->id!=src.office_change_fact_id||changed->kind!="organization_office_changed"||changed->domain!="organization"||!positions.count(row.first)||!positions.count(src.office_change_fact_id)||positions.at(src.office_change_fact_id)!=positions.at(row.first)+1||(have&&positions.at(row.first)<=previous_position)||src.tick<0||src.tick<previous_tick||src.tick>c.tick()||b.actor_id!=src.authority.actor_id||!c.actor(b.actor_id)||!request||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*request||b.request_sequence<=requests[b.actor_id]||b.result_revision<=previous_revision||b.result_revision>c.revision())return common_failure("PoliticalDismissalResultBindingMismatch",row.first);
  const HistoryRecord* prior=nullptr;Integer found=0;for(const auto& h:c.state().history){if(h.result_id==b.result_id){if(++found!=1||h.actor_id!=b.actor_id||h.kind!="political_dismiss"||h.tick!=src.tick)return common_failure("PoliticalDismissalHistoryMismatch",row.first);if(prior){auto lower=organization_instance_sequence(prior->result_id,"result");if(!lower||*lower>=*n)return common_failure("PoliticalDismissalResultIntervalMismatch",row.first);}}prior=&h;}
  previous_result=*result;previous_revision=b.result_revision;previous_tick=src.tick;requests[b.actor_id]=b.request_sequence;previous_position=positions.at(row.first);have=true;
 }
 for(const auto& h:c.state().history)if(h.kind=="political_dismiss"&&!results.count(h.result_id))return common_failure("PoliticalDismissalHistorySourceRequired",h.result_id);return common_success();
}
}
Outcome<StableId> political_dismissal_new_result_source(const PoliticalDismissalSourceState& before,const PoliticalDismissalSourceState& after,const StableId& actor,const StableId& kind,Integer tick){const auto fail=[]()->Outcome<StableId>{return {false,{},common_failure("PoliticalDismissalNewSourceRequired").error};};if(before.version!=1||after.version!=1||after.dismissals.size()<before.dismissals.size())return fail();const bool dismiss=kind=="political_dismiss";if(after.dismissals.size()!=before.dismissals.size()+(dismiss?1:0))return fail();for(std::size_t i=0;i<before.dismissals.size();++i)if(before.dismissals.rows()[i].first!=after.dismissals.rows()[i].first||!before.dismissals.rows()[i].second.actual_result)return fail();auto remainder=after;if(dismiss){const auto& row=after.dismissals.rows().back();if(row.first!=row.second.source.dismissal_fact_id||row.second.actual_result||row.second.source.authority.actor_id!=actor||row.second.source.tick!=tick)return fail();remainder.dismissals.erase(row.first);}if(!compare_boundary(encode_political_dismissal_sources(before),encode_political_dismissal_sources(remainder)).exact())return fail();return {true,dismiss?after.dismissals.rows().back().first:StableId{},{}};}
Status bind_political_dismissal_result(const CommonStore& c,PoliticalDismissalSourceState& state,const StableId& id,const StableId& actor,Integer sequence,const CommitResult& r,const PoliticalDismissalResultMatch& match){const auto* source=state.dismissals.find(id);const auto* cached=c.state().results.find(actor+":"+std::to_string(sequence));const auto* request=c.state().request_sequences.find(actor);if(!source||source->actual_result||source->source.authority.actor_id!=actor||source->source.tick!=r.tick||!r.ok||r.kind!="political_dismiss"||r.tick!=c.tick()||r.revision!=c.revision()||!cached||cached->get()!=&r||!request||*request!=sequence||!match||!match(r,id,source->source.office_change_fact_id)||c.state().history.empty())return common_failure("PoliticalDismissalActualResultRequired",id);const auto& h=c.state().history.back();if(h.result_id!=r.result_id||h.actor_id!=actor||h.kind!=r.kind||h.tick!=r.tick)return common_failure("PoliticalDismissalActualHistoryRequired",id);auto next=state;next.dismissals.find(id)->actual_result=PoliticalDismissalResultBinding{actor,r.result_id,sequence,r.revision};auto valid=bindings(c,next);if(!valid.ok)return valid;state=std::move(next);return common_success();}
Status validate_political_dismissal_results(const CommonStore& c,const PoliticalDismissalSourceState& s,const PoliticalDismissalResultMatch& match){auto valid=bindings(c,s);if(!valid.ok)return valid;std::set<StableId> seen;for(const auto& row:c.state().results.rows()){if(!row.second||row.second->kind!="political_dismiss")continue;const auto& r=*row.second;const PoliticalDismissalSourceRecord* source=nullptr;for(const auto& item:s.dismissals.rows())if(item.second.actual_result&&item.second.actual_result->result_id==r.result_id){if(source)return common_failure("PoliticalDismissalCachedSourceMismatch",row.first);source=&item.second;}if(!source||!r.ok||!match||!match(r,source->source.dismissal_fact_id,source->source.office_change_fact_id)||!seen.insert(source->source.dismissal_fact_id).second||r.tick!=source->source.tick||r.revision!=source->actual_result->result_revision||row.first!=source->actual_result->actor_id+":"+std::to_string(source->actual_result->request_sequence)||std::count_if(c.state().history.begin(),c.state().history.end(),[&](const auto& h){return h.result_id==r.result_id;})!=1)return common_failure("PoliticalDismissalCachedSourceMismatch",row.first);}return common_success();}
}
